@import '../../utils/forced-colors.css';

:host {
  display: block;
  box-sizing: border-box;
  min-width: 0;
  padding: var(--dimension-space-100);
  border-block-end: var(--dimension-stroke-width-012) solid var(--color-border-tertiary);
}

.inline-banner-settings__content {
  padding-block: var(--dimension-space-050);
  padding-inline: var(--dimension-space-075);
}

ds-text.inline-banner-settings__description {
  overflow-wrap: anywhere;
  padding-inline: var(--dimension-space-025);
}

@media (forced-colors: active) {
  :host {
    border-block-end-color: var(--ds-forced-color-content);
  }
}

import { Component, h, Host, Prop } from '@stencil/core';

@Component({
  tag: 'ds-inline-banner-settings',
  styleUrl: 'InlineBannerSettings.css',
  scoped: true,
})
export class InlineBannerSettings {
  /** Authored informational copy rendered without transformation. */
  @Prop() description!: string;

  render() {
    return (
      <Host>
        {/* eslint-disable-next-line compomo/prefer-direct-ds-text -- This structural layer owns the banner's inner padding separately from the ds-text balance padding. */}
        <div class="inline-banner-settings__content">
          <ds-text
            class="inline-banner-settings__description"
            as="p"
            variant="text-body-small"
            color="secondary"
          >
            {this.description}
          </ds-text>
        </div>
      </Host>
    );
  }
}
